"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { apiGet, apiPost, fmt, newIdempotencyKey, prettyDate, type Envelope } from "@/lib/api";
import { useSession } from "@/components/session-provider";

// API response records have endpoint-specific shapes generated by the FastAPI OpenAPI contract.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;
type Evidence = Row & { evidence_id: string };
function useLoad<T>(path: string) {
  const { session } = useSession(); const [data,setData]=useState<T|null>(null); const [error,setError]=useState(""); const [busy,setBusy]=useState(true);
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(()=>{let active=true;setBusy(true);setError("");apiGet<T>(path,session,{cacheMs:15000}).then(v=>{if(active)setData(v)}).catch(e=>{if(active)setError(e instanceof Error?e.message:"Could not load data")}).finally(()=>{if(active)setBusy(false)});return()=>{active=false}},[path,session]);
  return {data,error,busy,session};
}
function PageTitle({eyebrow,title,description,action}:{eyebrow:string;title:string;description:string;action?:React.ReactNode}) { return <div className="page-title"><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1><p>{description}</p></div>{action}</div>; }
function State({busy,error,empty,children}:{busy:boolean;error:string;empty?:boolean;children:React.ReactNode}) { if(busy)return <div className="state-card" role="status"><span className="spinner"/> Loading authorized tenant data…</div>;if(error)return <div className="state-card error" role="alert"><strong>Data unavailable</strong><p>{error}</p><p className="muted">Check API/database availability. No sample values are shown as live data.</p></div>;if(empty)return <div className="state-card">No observations are available for this tenant and time window.</div>;return <>{children}</>; }
function Metric({label,value,detail,tone=""}:{label:string;value:React.ReactNode;detail:string;tone?:string}){return <article className="metric-card"><div className="metric-top"><span>{label}</span><span className={`metric-glyph ${tone}`} aria-hidden="true">◌</span></div><strong>{value}</strong><p>{detail}</p></article>}
function Section({title,aside,children}:{title:string;aside?:React.ReactNode;children:React.ReactNode}){return <section className="panel"><div className="panel-heading"><h2>{title}</h2>{aside}</div>{children}</section>}
function EvidenceLink({id}:{id:string}){const [item,setItem]=useState<Evidence|null>(null);const [error,setError]=useState("");const {session}=useSession();async function show(){setError("");try{setItem(await apiGet(`/api/v1/evidence/${encodeURIComponent(id)}`,session))}catch(e){setItem(null);setError(e instanceof Error?e.message:"Evidence could not be verified")}}return <><button className="text-button" onClick={show}>{id}</button>{(item||error)&&<div className="drawer-backdrop" role="presentation" onClick={()=>{setItem(null);setError("")}}><aside className="source-drawer" role="dialog" aria-modal="true" aria-labelledby="evidence-title" onClick={e=>e.stopPropagation()}><button className="close-button" onClick={()=>{setItem(null);setError("")}} aria-label="Close source">×</button><p className="eyebrow">SOURCE VERIFICATION</p><h2 id="evidence-title">Evidence pointer</h2>{error?<div className="notice danger"><strong>Verification failed</strong><p>{error}</p></div>:item&&<><p className="notice">Resolved against the authenticated tenant’s evidence ledger.</p><dl className="details"><div><dt>Device</dt><dd>{fmt(item.device_id)}</dd></div><div><dt>Source field</dt><dd>{fmt(item.field_path)}</dd></div><div><dt>Observed value</dt><dd>{fmt(item.field_value)}</dd></div><div><dt>Captured</dt><dd>{prettyDate(item.collected_at)}</dd></div><div><dt>Dataset SHA-256</dt><dd className="wrap">{fmt(item.dataset_sha256)}</dd></div><div><dt>Value hash</dt><dd className="wrap">{fmt(item.field_value_hash)}</dd></div><div><dt>Classification</dt><dd>{fmt(item.content_classification)}</dd></div></dl><small className="muted">Telemetry text is untrusted source data. It is displayed as text only.</small></>}</aside></div>}</>}
function AsOf({data}:{data:Row}){return <div className="asof"><span className="asof-icon" aria-hidden="true">◷</span><div><strong>Historical telemetry</strong><span>Data as of {prettyDate(data.data_as_of)} · captured May–June 2026</span></div><span className="pill neutral">Not live</span></div>}

export function Overview(){const {data,error,busy}=useLoad<Envelope<Row>>("/api/v1/fleet/summary");const envelope=data??{};const summary=envelope.items?.[0]??{};const insights=summary.insights??[];const high=summary.observed_high_severity_fail_count;
 return <><PageTitle eyebrow="FLEET OVERVIEW" title="Good morning, operations" description="A clear view of what the telemetry can support — and where the data stops." action={<Link className="button primary" href="/copilot">Start an investigation <span aria-hidden="true">↗</span></Link>}/><State busy={busy} error={error}><>{data&&<AsOf data={envelope as Row}/>}<div className="metric-grid"><Metric label="Devices in scope" value={fmt(summary.inventory_count)} detail="Latest eligible inventory observations"/><Metric label="High severity failures" value={high===undefined?"Unknown":high} detail="Observed source severity · fail only" tone="green"/><Metric label="Ranked findings" value={fmt(summary.insight_count)} detail="Deterministic policy signals" tone="amber"/><Metric label="Coverage" value={envelope.coverage?"Available":"Not reported"} detail="Missing telemetry remains unknown" tone="blue"/></div><div className="two-col"><Section title="Attention signals" aside={<Link href="/insights" className="text-link">All findings →</Link>}>{insights.length?<div className="signal-list">{insights.slice(0,4).map((x:Row,i:number)=><Link href="/insights" className="signal-row" key={x.insight_id??i}><span className={`severity-dot ${String(x.severity_heuristic??"").toLowerCase()}`} aria-hidden="true"/><span><strong>{x.headline??x.kind}</strong><small>{x.device_ids?.length??0} devices · {x.numerator??"—"}/{x.denominator??"—"} observed</small></span><span className="arrow">→</span></Link>)}</div>:<p className="empty-inline">No ranked findings returned. This does not establish that every device is healthy.</p>}</Section><Section title="Compliance evidence" aside={<Link href="/trust" className="text-link">Review provenance →</Link>}><div className="compliance-summary"><div className="compliance-number"><strong>{high===undefined?"—":high}</strong><span>high severity<br/>failures observed</span></div><div><p>Failure requires both <code>status=fail</code> and source severity <code>high</code>.</p><p className="muted">Coverage: {JSON.stringify(envelope.coverage?.observed_high_severity_compliance??"Not reported")}</p></div></div></Section></div><Section title="Fleet coverage"><div className="coverage-grid">{Object.entries(envelope.coverage??{}).map(([name,value])=><div key={name}><strong>{name.replaceAll("_"," ")}</strong><span>{JSON.stringify(value)}</span></div>)}</div><p className="footnote">Unknown and absent values are not counted as normal or zero. RAM utilization is a telemetry proxy, not proof of slow application performance.</p></Section></></State></>;
}

export function Devices(){const {data,error,busy}=useLoad<Envelope<Row>>("/api/v1/devices?page=1&page_size=100");const [query,setQuery]=useState("");const [platform,setPlatform]=useState("all");const [sort,setSort]=useState("collected_at");const items=(data?.items??[]).filter(x=>`${x.device_id} ${x.platform} ${x.model}`.toLowerCase().includes(query.toLowerCase())&&(platform==="all"||String(x.platform).toLowerCase().includes(platform))).sort((a,b)=>String(b[sort]??"").localeCompare(String(a[sort]??"")));return <><PageTitle eyebrow="INVENTORY" title="Devices" description="Latest eligible observation per device, with primary volume and source timestamp."/><div className="toolbar"><label className="search">Search device, platform or model<input value={query} onChange={e=>setQuery(e.target.value)} placeholder="e.g. MacBook Pro"/></label><label>Platform<select value={platform} onChange={e=>setPlatform(e.target.value)}><option value="all">All platforms</option><option value="mac">macOS</option><option value="windows">Windows</option></select></label><label>Sort by<select value={sort} onChange={e=>setSort(e.target.value)}><option value="collected_at">Latest observation</option><option value="device_id">Device ID</option><option value="platform">Platform</option><option value="disk_free_percent">Disk free</option></select></label><span className="muted">{data?.total_count??"—"} records</span></div><State busy={busy} error={error} empty={!busy&&!error&&!items.length}><div className="table-wrap"><table><thead><tr><th>Device</th><th>Platform / version</th><th>Primary disk</th><th>RAM</th><th>Battery observation</th><th>Latest observed (UTC)</th></tr></thead><tbody>{items.map((d,i)=><tr key={`${d.device_id}-${i}`}><td><Link href={`/devices/${encodeURIComponent(d.device_id)}`} className="device-link">{d.device_id}</Link><small>{d.model??"Model unknown"} · owner details withheld</small></td><td>{d.platform??"Unknown"}<small>{d.product_version??"Version unknown"}</small></td><td>{d.primary_disk_mount??"Primary volume unknown"}<small>{fmt(d.disk_free_percent,"% free")}</small></td><td>{fmt(d.ram_utilization,"% used")}</td><td>{d.battery_condition??"Unknown / not observed"}</td><td>{prettyDate(d.collected_at)}</td></tr>)}</tbody></table></div><p className="footnote">Owner names are not displayed in this console. Unknown means no verified observation was returned.</p></State></>}

export function Insights(){const {data,error,busy}=useLoad<Envelope<Row>>("/api/v1/insights");const [selected,setSelected]=useState<Row|null>(null);const items=data?.items??[];return <><PageTitle eyebrow="DETERMINISTIC ANALYTICS" title="Insights" description="Ranked findings from observed history. Severity labels are policy heuristics, not reported compliance severity."/><State busy={busy} error={error} empty={!busy&&!error&&!items.length}><div className="insight-list">{items.map((x,i)=><article className="insight-card" key={x.insight_id??i}><div className="insight-rank">{String(i+1).padStart(2,"0")}</div><div className="insight-content"><div className="tag-row"><span className={`pill ${String(x.severity_heuristic??"unknown").toLowerCase()}`}>{x.severity_heuristic??"Unknown severity"}</span><span className="pill neutral">{String(x.kind??"Finding").replaceAll("_"," ")}</span></div><h2>{x.headline??"Untitled finding"}</h2><p>{x.explanation??"No explanation supplied."}</p><div className="insight-meta"><span>{x.device_ids?.length??0} devices</span><span>{x.numerator??"—"}/{x.denominator??"—"} readings</span><span>Coverage {x.coverage?.fraction??x.coverage?.coverage_percent??"Unknown"}</span><span>{prettyDate(x.latest_observed_at)}</span></div><button className="button secondary small" onClick={()=>setSelected(x)}>Explain finding</button></div></article>)}</div></State>{selected&&<div className="drawer-backdrop" onClick={()=>setSelected(null)}><aside role="dialog" aria-modal="true" className="source-drawer" onClick={e=>e.stopPropagation()}><button className="close-button" onClick={()=>setSelected(null)} aria-label="Close insight">×</button><p className="eyebrow">POLICY EXPLANATION</p><h2>{selected.headline??selected.kind}</h2><dl className="details"><div><dt>Rule / policy</dt><dd>{selected.policy_version??data?.policy_version??"Unknown"}</dd></div><div><dt>Window</dt><dd>{prettyDate(selected.window_start)} – {prettyDate(selected.window_end)}</dd></div><div><dt>Coverage</dt><dd>{JSON.stringify(selected.coverage??{})}</dd></div><div><dt>Method</dt><dd>{selected.explanation??"No method explanation returned."}</dd></div><div><dt>Limitations</dt><dd>{(selected.limitations??[]).join("; ")||"No limitations returned"}</dd></div><div><dt>Suggested actions (not executed)</dt><dd>{(selected.suggested_action_kinds??[]).join(", ")||"None"}</dd></div><div><dt>Evidence</dt><dd>{(selected.evidence_ids??[]).map((id:string)=><EvidenceLink key={id} id={id}/>)}</dd></div></dl><pre className="readings">{JSON.stringify(selected.readings??selected.evidence_manifest??[],null,2)}</pre></aside></div>}</>}

export function Copilot(){const {session}=useSession();const [question,setQuestion]=useState("");const [busy,setBusy]=useState(false);const [run,setRun]=useState<Row|null>(null);const [error,setError]=useState("");async function ask(q=question){if(!q.trim()||busy)return;setQuestion(q);setBusy(true);setError("");setRun(null);try{const result=await apiPost<Row>("/api/v1/agent/runs",session,{question:q},newIdempotencyKey());setRun(result)}catch(e){setError(e instanceof Error?e.message:"Run failed")}finally{setBusy(false)}}const examples=["Which devices have less than 20% disk free?","How many high severity compliance failures were observed?","What is the exact battery health percentage?"];return <><PageTitle eyebrow="EVIDENCE-LED INVESTIGATION" title="Fleet copilot" description="Ask a fleet question. The system selects bounded read tools, verifies evidence, then reports supported claims."/><div className="copilot-layout"><section className="panel copilot-main"><div className="stepper" aria-label="Investigation stages">{["Planning","Querying","Verifying","Answered"].map((s,i)=><div className={busy&&i<2||run&&i===3?"step active":"step"} key={s}><span>{String(i+1).padStart(2,"0")}</span>{s}</div>)}</div><label className="question-label" htmlFor="question">What would you like to investigate?</label><textarea id="question" maxLength={2000} value={question} onChange={e=>setQuestion(e.target.value)} placeholder="Ask about disk, compliance, battery observations, or trends…"/><div className="compose-footer"><span>{question.length}/2000</span><button className="button primary" disabled={busy||!question.trim()} onClick={()=>ask()}>{busy?"Investigating…":"Run investigation"}</button></div><div className="example-prompts"><span>TRY AN EXAMPLE</span>{examples.map(x=><button key={x} onClick={()=>ask(x)} disabled={busy}>{x}</button>)}</div>{error&&<div role="alert" className="notice danger">{error}</div>}{run&&<><div className="answer-box"><div className="tag-row"><span className="pill blue">Verified response</span>{run.answer?.abstained&&<span className="pill amber">Insufficient evidence</span>}</div><p>{run.answer?.text??"No answer text returned."}</p>{(run.answer?.gaps??[]).map((g:string,i:number)=><p className="muted" key={i}>Limitation: {g}</p>)}{(run.answer?.claims??[]).length>0&&<div className="claims"><strong>Supported claims</strong>{run.answer.claims.map((c:Row,i:number)=><div className="claim" key={i}><span>{c.text??JSON.stringify(c)}</span>{(c.evidence_ids??[]).map((id:string)=><EvidenceLink id={id} key={id}/>)}{(c.manifest_ids??[]).map((id:string)=><span className="manifest" key={id}>Manifest {id}</span>)}</div>)}</div>}</div><Section title="Graph step trace"><TraceSteps events={run.step_events??[]}/></Section><Section title="Operation trace"><div className="timeline">{(run.trace??[]).map((t:Row,i:number)=><div className="timeline-row" key={i}><span className="timeline-mark">{String(i+1).padStart(2,"0")}</span><span><strong>{t.operation??t.tool??"Authorized operation"}</strong><small>{t.success===false?"Failed safely":"Tool result recorded"} · {(t.evidence_ids??[]).length} evidence references</small></span><span className="pill neutral">{t.duration_ms??0} ms</span></div>)}{!(run.trace??[]).length&&<p className="muted">No tool operation was required for this response.</p>}</div></Section><p className="footnote">Trace {run.trace_id??run.run_id} · graph {run.versions?.graph_version} · policy {run.versions?.policy_version} · model {run.versions?.model_version}. Events contain structured decisions and sanitized summaries, never private reasoning.</p></>}</section><aside className="panel side-panel"><span className="eyebrow">INVESTIGATION BOUNDARY</span><h2>Evidence before explanation</h2><p>Answers cite tenant-authorized evidence. Unsupported requests return a refusal or an explicit data gap.</p><div className="side-stat"><strong>12</strong><span>maximum read calls per run</span></div><div className="side-stat"><strong>0</strong><span>external action executors available to copilot</span></div><p className="footnote">Telemetry text is treated as untrusted data and never as instructions.</p></aside></div></>}

function TraceSteps({ events }: { events: Row[] }) {
  return (
    <div className="timeline">
      {events.map((entry: Row, i: number) => {
        const event = entry.event ?? entry;
        const tools = event.plan_summary?.tools ?? [];
        const evidenceCount = event.evidence_ids?.length ?? 0;
        return (
          <div className="timeline-row" key={entry.step_index ?? i}>
            <span className="timeline-mark">{String(entry.step_index ?? i).padStart(2, "0")}</span>
            <span>
              <strong>{event.node ?? "graph"}{event.tool_name ? ` · ${event.tool_name}` : ""}</strong>
              <small>
                {event.decision ?? "step recorded"}
                {tools.length ? ` · tools ${tools.join(", ")}` : ""}
                {evidenceCount ? ` · ${evidenceCount} evidence IDs` : ""}
              </small>
            </span>
            <span className="pill neutral">{event.duration_ms ?? entry.elapsed_ms ?? 0} ms</span>
          </div>
        );
      })}
      {!events.length && <p className="muted">No graph step events returned.</p>}
    </div>
  );
}

export function Actions(){const {session}=useSession();const queue=useLoad<Envelope<Row>>("/api/v1/actions/proposals?page=1&page_size=100");const [id,setId]=useState("");const [proposal,setProposal]=useState<Row|null>(null);const [audit,setAudit]=useState<Row|null>(null);const [error,setError]=useState("");const [busy,setBusy]=useState(false);const [check,setCheck]=useState(false);const [executeCheck,setExecuteCheck]=useState(false);const [draftTarget,setDraftTarget]=useState("");const [draftManifest,setDraftManifest]=useState("");const [draftSpec,setDraftSpec]=useState("");async function load(){if(!/^\d+$/.test(id))return setError("Enter a numeric proposal ID.");setCheck(false);setExecuteCheck(false);setBusy(true);setError("");try{setProposal(await apiGet(`/api/v1/actions/proposals/${id}`,session));setAudit(await apiGet(`/api/v1/actions/proposals/${id}/audit`,session))}catch(e){setError(e instanceof Error?e.message:"Proposal unavailable");setProposal(null)}finally{setBusy(false)}}async function draft(){setBusy(true);setError("");try{const created=await apiPost<Row>("/api/v1/actions/proposals",session,{action_kind:"create_upgrade_order",target_id:draftTarget,payload:{component:"memory",spec:draftSpec},evidence_manifest_ids:[draftManifest],mode:"SANDBOX_SIMULATION"},newIdempotencyKey());setProposal({proposal_id:created.proposal_id,proposal_hash:created.proposal_hash,status:created.status,proposal:created.proposal,approvals:[]});setId(String(created.proposal_id));setError("Proposal created for human review. No external order was submitted.")}catch(e){setError(e instanceof Error?e.message:"Proposal could not be created")}finally{setBusy(false)}}async function decide(decision:"approve"|"reject"){if(!proposal)return;setBusy(true);setError("");try{await apiPost(`/api/v1/actions/proposals/${proposal.proposal_id}/decision`,session,{decision,proposal_hash:proposal.proposal_hash},newIdempotencyKey());await load()}catch(e){setError(e instanceof Error?e.message:"Decision failed")}finally{setBusy(false)}}async function execute(){if(!proposal||!executeCheck)return;setBusy(true);setError("");try{await apiPost(`/api/v1/actions/proposals/${proposal.proposal_id}/execute`,session,{proposal_hash:proposal.proposal_hash},newIdempotencyKey());setExecuteCheck(false);await load()}catch(e){setError(e instanceof Error?e.message:"Sandbox execution failed")}finally{setBusy(false)}}const doc=proposal?.proposal??proposal?.proposal_json;const canReview=(session.role==="approver"||session.role==="admin")&&proposal?.status==="PENDING_APPROVAL"&&doc?.actor_id!==`fixture-${session.tenant}-${session.role}`;
 return <><PageTitle eyebrow="HUMAN APPROVAL" title="Action proposals" description="Review the exact immutable operation, evidence, policy and decision history. Approval never means execution."/><div className="sandbox-banner"><span aria-hidden="true">▣</span><div><strong>SANDBOX SIMULATION ONLY</strong><span>No external orders, tickets, replacements, or messages are sent by this console.</span></div></div><Section title="Proposal queue"><State busy={queue.busy} error={queue.error} empty={!queue.busy&&!queue.error&&!(queue.data?.items?.length)}><div className="table-wrap"><table><thead><tr><th>Proposal</th><th>Action</th><th>Target</th><th>Mode</th><th>Status</th><th>Created</th></tr></thead><tbody>{(queue.data?.items??[]).map((x:Row)=><tr key={x.proposal_id}><td><button className="text-button" onClick={()=>{setId(String(x.proposal_id));void apiGet<Row>(`/api/v1/actions/proposals/${x.proposal_id}`,session).then(setProposal).catch(e=>setError(e.message));void apiGet<Row>(`/api/v1/actions/proposals/${x.proposal_id}/audit`,session).then(setAudit).catch(()=>setAudit(null))}}>#{x.proposal_id}</button></td><td>{x.proposal?.action_kind}</td><td>{x.proposal?.target_id}</td><td><span className="pill amber">{x.proposal?.mode}</span></td><td>{x.status}</td><td>{prettyDate(x.created_at)}</td></tr>)}</tbody></table></div></State></Section>{session.role!=="viewer"&&<Section title="Draft sandbox proposal"><p className="footnote">Creates an immutable proposal for review. Evidence manifest and target are validated by the server. This form cannot execute an action.</p><div className="toolbar"><label>Device ID<input value={draftTarget} onChange={e=>setDraftTarget(e.target.value)} maxLength={255}/></label><label>Evidence manifest ID<input value={draftManifest} onChange={e=>setDraftManifest(e.target.value)} maxLength={80}/></label><label>Memory specification<input value={draftSpec} onChange={e=>setDraftSpec(e.target.value)} maxLength={500} placeholder="e.g. 16 GB compatible memory module"/></label><button className="button primary" disabled={busy||!draftTarget||!draftManifest||!draftSpec} onClick={draft}>Create proposal</button></div></Section>}<Section title="Open a proposal"><div className="toolbar"><label>Proposal ID<input value={id} onChange={e=>setId(e.target.value)} inputMode="numeric" placeholder="e.g. 1042"/></label><button className="button secondary" onClick={load} disabled={busy}>Load scoped proposal</button><span className="muted">Role: {session.role}</span></div>{error&&<p role="alert" className="notice danger">{error}</p>}{proposal&&<div className="proposal-detail"><div className="proposal-head"><div><span className="pill neutral">{proposal.status}</span> <span className="pill amber">{doc?.mode??"Mode unknown"}</span></div><strong>SHA-256 · {proposal.proposal_hash}</strong></div><dl className="details"><div><dt>Exact action</dt><dd>{doc?.action_kind??"Unknown"}</dd></div><div><dt>Target</dt><dd>{doc?.target_type} / {doc?.target_id}</dd></div><div><dt>Tenant and actor</dt><dd>{doc?.tenant_key} · {doc?.actor_id}</dd></div><div><dt>Payload</dt><dd><pre className="readings">{JSON.stringify(doc?.payload??{},null,2)}</pre></dd></div><div><dt>Evidence manifests</dt><dd>{(doc?.evidence_manifest_ids??[]).map((x:string)=><span className="manifest" key={x}>{x} </span>)}</dd></div><div><dt>Policy facts</dt><dd><pre className="readings">{JSON.stringify(doc?.policy_facts??{},null,2)}</pre></dd></div><div><dt>Data as of / expires</dt><dd>{prettyDate(doc?.data_as_of)} / {prettyDate(doc?.expires_at)}</dd></div><div><dt>Policy / graph</dt><dd>{doc?.policy_version} / {doc?.graph_version}</dd></div><div><dt>Approvals</dt><dd>{(proposal.approvals??[]).map((x:Row,i:number)=><p key={i}>{x.decision} · {x.actor_role} · {prettyDate(x.decided_at)}</p>)}</dd></div><div><dt>Status history</dt><dd>{(audit?.events??[]).map((x:Row,i:number)=><p key={i}>{x.event_type} · {prettyDate(x.created_at)}</p>)}</dd></div></dl>{proposal.status==="PENDING_APPROVAL"&&<div className="confirm-area"><label><input type="checkbox" checked={check} onChange={e=>setCheck(e.target.checked)}/> I reviewed this immutable operation, target, evidence, policy facts and simulation mode.</label><div className="button-row"><button className="button primary" disabled={!canReview||!check||busy} onClick={()=>decide("approve")}>Approve proposal</button><button className="button danger-button" disabled={!canReview||busy} onClick={()=>decide("reject")}>Reject proposal</button></div><p className="footnote">Approver must be a different actor from the requester. Server checks remain authoritative.</p></div>}{proposal.status==="APPROVED"&&session.role==="operator"&&<div className="confirm-area"><p className="footnote">Approval is complete. This separately authorized step records a sandbox result only; no external system is contacted.</p><label><input type="checkbox" checked={executeCheck} onChange={e=>setExecuteCheck(e.target.checked)}/> I confirm this exact approved proposal may be simulated.</label><button className="button primary" disabled={!executeCheck||busy} onClick={execute}>Run sandbox simulation</button></div>}{proposal.status==="APPROVED"&&session.role!=="operator"&&!proposal.execution&&<p className="notice">Approved. An operator must separately confirm sandbox simulation.</p>}{proposal.execution&&<p className="notice">Recorded result: {JSON.stringify(proposal.execution)}</p>}</div>}</Section></>}

export function Trust(){const audit=useLoad<Row>("/api/v1/audit?page=1&page_size=50");const evals=useLoad<Row>("/api/v1/evaluations/latest");const [runId,setRunId]=useState("");const [run,setRun]=useState<Row|null>(null);const [err,setErr]=useState("");return <><PageTitle eyebrow="PROVENANCE & CONTROLS" title="Trust center" description="Tenant-scoped audit activity, evaluation provenance, and sanitized operation traces."/><State busy={audit.busy||evals.busy} error={audit.error||evals.error}><div className="two-col"><Section title="Audit trail"><div className="timeline">{(audit.data?.items??audit.data?.events??[]).map((x:Row,i:number)=><div className="timeline-row" key={i}><span className="timeline-mark">{String(i+1).padStart(2,"0")}</span><span><strong>{x.event_type??x.action??"Audit event"}</strong><small>{prettyDate(x.created_at)} · {x.actor_id??"Actor redacted"}</small></span></div>)}{!(audit.data?.items??audit.data?.events??[]).length&&<p className="muted">No audit events returned for this tenant.</p>}</div></Section><Section title="Evaluation & provenance"><pre className="readings">{JSON.stringify(evals.data,null,2)}</pre><p className="footnote">Checked-in offline evaluation artifacts are not a live evaluation run.</p></Section></div><Section title="Inspect a completed run"><div className="toolbar"><label>Run ID<input value={runId} onChange={e=>setRunId(e.target.value)} placeholder="Tenant-scoped run reference"/></label><button className="button secondary" onClick={async()=>{setErr("");setRun(null);try{setRun(await apiGet(`/api/v1/agent/runs/${encodeURIComponent(runId)}`,audit.session))}catch(e){setErr(e instanceof Error?e.message:"Run unavailable")}}}>Load run trace</button></div>{err&&<p role="alert" className="notice danger">{err}</p>}{run&&<pre className="readings">{JSON.stringify({run_id:run.run_id,status:run.status,operations:run.operations??run.trace,versions:run.versions},null,2)}</pre>}</Section></State></>}

export function DeviceDetail({deviceId}:{deviceId:string}){const {session}=useSession();const [snapshot,setSnapshot]=useState<Row|null>(null);const [hist,setHist]=useState<Record<string,Row>>({});const [error,setError]=useState("");const [busy,setBusy]=useState(true);useEffect(()=>{let live=true;async function load(){setBusy(true);try{const raw=await apiGet<Row>(`/api/v1/devices/${encodeURIComponent(deviceId)}`,session);if(!live)return;const s={...(raw.items?.[0]??raw),data_as_of:raw.data_as_of,manifest_ids:raw.manifest_ids,data_sha256:raw.data_sha256};setSnapshot(s);const end=new Date(s.data_as_of??s.collected_at);const start=new Date(end.getTime()-30*86400000);const q=new URLSearchParams({metric:"disk_free_percent",start:start.toISOString(),end:end.toISOString(),resolution:"raw"});const [d,r]=await Promise.allSettled([apiGet<Envelope<Row>>(`/api/v1/devices/${encodeURIComponent(deviceId)}/history?${q}`,session),apiGet<Envelope<Row>>(`/api/v1/devices/${encodeURIComponent(deviceId)}/history?${new URLSearchParams({metric:"ram_utilization",start:start.toISOString(),end:end.toISOString(),resolution:"raw"})}`,session)]);if(live)setHist({disk:d.status==="fulfilled"?d.value:{error:d.reason?.message},ram:r.status==="fulfilled"?r.value:{error:r.reason?.message}})}catch(e){if(live)setError(e instanceof Error?e.message:"Device unavailable")}finally{if(live)setBusy(false)}}void load();return()=>{live=false}},[deviceId,session]);const battery=snapshot?.battery??{};return <><PageTitle eyebrow="DEVICE DETAIL" title={deviceId} description="Thirty-day history ending at the latest API data-as-of. Lines are not extrapolated." action={<Link href="/devices" className="button secondary">← All devices</Link>}/><State busy={busy} error={error}>{snapshot&&<><AsOf data={snapshot}/><div className="metric-grid"><Metric label="Primary disk" value={fmt(snapshot.primary_disk_mount)} detail={`${fmt(snapshot.disk_free_percent,"% free")} · source value`}/><Metric label="RAM utilization" value={fmt(snapshot.ram_utilization,"% used")} detail="Proxy metric; not proof of slow applications" tone="blue"/><Metric label="Battery condition" value={battery.condition??"Unknown"} detail={`Cycles ${fmt(battery.cycle_count)} · health percentage not derivable`} tone="amber"/><Metric label="Last observation" value={prettyDate(snapshot.collected_at)} detail="UTC source capture time"/></div><div className="two-col">{(["disk","ram"] as const).map(key=><HistoryPanel key={key} title={key==="disk"?"Disk free history":"RAM utilization history"} data={hist[key]} field={key==="disk"?"disk_free_percent":"ram_utilization"}/> )}</div><Section title="Compliance observations"><div className="table-wrap"><table><thead><tr><th>Check</th><th>Status</th><th>Source severity</th><th>Observed</th></tr></thead><tbody>{(snapshot.compliance??[]).map((c:Row,i:number)=><tr key={i}><td>{c.check_id}</td><td>{c.status}</td><td>{c.severity}</td><td>{prettyDate(c.collected_at)}</td></tr>)}{!(snapshot.compliance??[]).length&&<tr><td colSpan={4}>No compliance observations in this snapshot. Unknown is not passing.</td></tr>}</tbody></table></div></Section><Section title="Snapshot provenance"><dl className="details"><div><dt>Snapshot ID</dt><dd>{fmt(snapshot.snapshot_id)}</dd></div><div><dt>Manifest</dt><dd>{(snapshot.manifest_ids??[]).join(", ")||"Not returned"}</dd></div><div><dt>Dataset SHA-256</dt><dd>{(snapshot.data_sha256??[]).join(", ")||"Not returned"}</dd></div></dl>{(snapshot.evidence_ids??[]).map((id:string)=><EvidenceLink key={id} id={id}/>)}</Section></>}</State></>}
function HistoryPanel({title,data,field}:{title:string;data:Row;field:string}){const readings=data?.items??[];const value=(r:Row)=>r[field]??r.value;const valid=readings.filter((r:Row)=>typeof value(r)==="number");const max=Math.max(100,...valid.map((x:Row)=>Number(value(x))));const points=valid.map((r:Row,i:number)=>`${(i/(Math.max(1,valid.length-1)))*100},${100-(Number(value(r))/max)*90}`).join(" ");return <Section title={title}><div className="chart-caption">UTC · % {field==="disk_free_percent"?"free":"used"} · {valid.length} observed points</div>{data?.error?<p className="muted">History unavailable: {String(data.error)}</p>:valid.length?<><svg className="chart" viewBox="0 0 100 100" role="img" aria-label={`${title}, ${valid.length} recorded points. Exact data follows in a table.`}><line x1="0" y1="10" x2="100" y2="10"/><line x1="0" y1="50" x2="100" y2="50"/><line x1="0" y1="90" x2="100" y2="90"/><polyline points={points} /></svg><div className="table-wrap"><table><thead><tr><th>Observed (UTC)</th><th>Value</th><th>Observation validity</th></tr></thead><tbody>{valid.map((r:Row,i:number)=><tr key={i}><td>{prettyDate(r.collected_at)}</td><td>{fmt(value(r),"%")}</td><td>{r.valid===false?"Invalid source value":"Observed"}</td></tr>)}</tbody></table></div></>:<div className="unknown-box">No eligible history points. This is unknown, not zero or normal.</div>}</Section>}
